			function doPrgrsSttsUpdate(param) {
			    app.lookup("grdList").getCheckRowIndices().forEach(function(idx) {
			        app.lookup("dsList").setRowState(idx, cpr.data.tabledata.RowState.UPDATED);
			    });
			    
			    //파라미터 설정
			    app.lookup("subPrgrsSttsUpdate").setParameters("param", param);
			    
			    //저장 서브미션 호출
			    util.Submit.send(app, "subPrgrsSttsUpdate", function(pbSuccess) {
			        if (pbSuccess) {
			            app.lookup("dmSearch").build(searchRowData);
			            doList("save");
			        }
			    });
			}

